insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('bc68f5c4-2104-4d62-95e5-1e74d6111fbe','en','sechskies-hakwon-byeolgok','Sechskies - "Hakwon Byeolgok"','"Hakwon Byeolgok" is Sechskies'' rebellious 1997 debut song.','Sechskies'' 1997 debut title track "Hakwon Byeolgok" struck a chord with teenagers through its defiant lyrics criticizing Korea''s exam-obsessed education system and its intense performances, announcing the arrival of a first-generation idol group that stood alongside H.O.T.','Sechskies made their broadcast debut with "Hakwon Byeolgok" on KMTV''s "Show Music Tank" on April 15, 1997, and released the same-titled debut album on May 14 that year. The lyrics directly criticized problems in Korea''s exam-driven education system such as grade obsession, and the song''s unique arrangement blending a traditional Korean taryeong rap style with acrobatic group choreography made it a topic of conversation among teens, propelling it into the top 10 of the Gayo Top Ten chart. Alongside H.O.T., the song is seen as the opening shot in the rivalry that defined first-generation idols, and its rebellious message as a debut track is considered to have influenced idol groups that followed.','Can be cited as a representative example of a first-generation idol debut song.',null,array['학원별곡','Hakwon Byeolgok'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('aa390efd-1ba1-44c6-b493-2b046462ff4d','en','uh-if-you-draw-that-much','"Uh... If You Draw That Many?"','"Uh... if you draw that many?" is a famous Hearthstone catchphrase from streamer Looksam''s self-destructive Hakkar deck run.','The line originated in December 2018 when Hearthstone streamer Looksam (Kim Jin-hyo) was playing a Soulbound Hakkar deck in ranked play - knowing that drawing too many cards was dangerous, he couldn''t stop himself and ended up defeating himself. The phrase became a signature saying in the Hearthstone fandom for describing a situation where someone can''t stop even though they know the danger.','A remark made by streamer Looksam (Kim Jin-hyo) during a Hearthstone broadcast in December 2018.','Used to describe a situation where someone knows the risk but can''t stop themselves.',null,array['어~ 그렇게 드로우를 많이 하면?'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8e975be3-2469-4c4a-a776-a84dbae6ed0b','en','unyielding-heart','"What Matters Is an Unyielding Heart"','"What matters is an unyielding heart" is the rallying phrase that came to symbolize South Korea''s national football team at the 2022 Qatar World Cup.','Originally used within esports fandoms, the phrase spread rapidly after South Korea''s national team overcame poor results against Uruguay and Ghana to advance to the round of 16 with a dramatic comeback win over Portugal at the 2022 Qatar World Cup group stage in November-December 2022. Repeated in the media, on social media, and in advertising as the abbreviation "Junggkkeokma," it became a defining catchphrase of the latter half of 2022. It continues to be widely used as a vow not to give up in difficult situations such as sports, exams, or job hunting.','A rallying phrase that gained renewed attention during South Korea''s run to the round of 16 at the 2022 Qatar World Cup.','Can be used by anyone as a vow or word of encouragement not to give up in difficult situations.',null,array['중요한 건 꺾이지 않는 마음','Junggkkeokma','중꺾마','중꺾마 정신'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('3840e458-bfec-497c-bd91-574ca6c4f019','en','hwang-hee-chan-shirtless-celebration','Hwang Hee-chan''s Shirtless Celebration','Hwang Hee-chan''s shirtless celebration refers to him ripping off his jersey after scoring a last-minute winner against Portugal at the 2022 World Cup.','In added time of the second half of South Korea''s final group-stage match against Portugal at the 2022 Qatar World Cup, Hwang Hee-chan scored the winning goal and received a yellow card for tearing off his jersey in celebration. The goal sent South Korea to the World Cup round of 16 for the first time in 12 years, and both the celebration and Hwang''s nickname "Jeotso" (literally "dairy cow") became a huge topic of conversation.','Hwang Hee-chan''s winning-goal celebration in South Korea''s group-stage match against Portugal at the 2022 Qatar World Cup.','Used to express a dramatic victory or an exhilarating moment.',null,array['황희찬 웃통 탈의 세리머니','Hwang Hee-chan''s Winning Goal Celebration','황희찬 결승골 세리머니','Jeotso (Dairy Cow)','젖소'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9266e072-5ccb-4386-99cd-14e631972eff','en','baby-shark-challenge','Baby Shark Challenge','The Baby Shark Challenge is a dance challenge where people copy Pinkfong''s "Baby Shark" dance and post it on social media.','In the summer of 2018, the dance version of Pinkfong''s "Baby Shark" exploded in popularity across the US and Europe, growing into a challenge that even celebrities took part in. Stars like Ellen DeGeneres and James Corden joined in, and in Korea too the song''s addictive hook became a topic of conversation not just among children but adults as well.','SmartStudy''s (Pinkfong''s) "Baby Shark Dance" video, first posted in 2016 and spread as a challenge in 2018.','Cited as an example of the global success of Korean content.',null,array['아기상어 챌린지','베이비샤크 댄스 챌린지','Baby Shark Challenge'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('2f6da376-12eb-4c66-88b1-96bb4b5eb07d','en','ri-jung-ttak','"Ri-Jung-Ttak" ("Liverpool''s Perfect for Mid-Table")','"Ri-Jung-Ttak" is a football meme that grew out of a sensationalized mistranslation of a manager''s comment and was popularized by streamer Gamst''s parody song.','The meme originated when Korean media sensationally mistranslated Sunderland manager Gus Poyet''s 2014 remark that "Liverpool would be a mid-table side without Suarez" as "Liverpool is perfect for mid-table." Streamer Gamst (BJ Gamst) popularized it further by rewriting the lyrics of Song Dae-kwan''s "Yuhaengga" ("Popular Song") into the catchy "Ri-jung-ttak, ri-jung-ttak, a joyful song." It has since become a football community meme used as a mocking reference whenever anything related to Liverpool comes up.','A mistranslated 2014 article quoting manager Gus Poyet''s remark, combined with the popularity of streamer Gamst''s parody song.','Used in football/Liverpool-related jokes.',null,array['리중딱(리버풀은 중위권이 딱이야)','리버풀은 중위권이 딱이야','Liverpool''s Perfect for Mid-Table','리중딱송'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('3a805bf1-982b-451d-8a15-7348c96a0bda','en','seo-taiji-ultramania','Seo Taiji - "Ultramania"','"Ultramania" is Seo Taiji''s 2000 comeback single, which sold 900,000 first-day copies.','The title track of Seo Taiji''s sixth studio album introduced the then-unfamiliar nu-metal genre to Korea''s mainstream music market. It sold 900,000 copies on its first day of release, the highest first-day sales in Korean music history at the time, and drew attention for its unconventional sound exploring the psychology of "mania," or single-minded obsession.','Released on September 8, 2000 as the title track of Seo Taiji''s sixth studio album comeback.','Used when discussing Seo Taiji''s comeback or early-2000s rock/metal sound.',null,array['서태지 - 울트라맨이야','Seo Taiji 6th Album Title Track','서태지 6집 타이틀곡'],'[{"text": "This album''s first-day sales are basically Seo Taiji Ultramania level.", "situation": "KakaoTalk"}, {"text": "The impact of Seo Taiji''s comeback back then was insane.", "situation": "Social media comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7ed5b9ee-ea54-4490-befb-0a475fcf0e8a','en','woo-young-woo-whale-imagination','Woo Young-woo''s Whale Imagination','Woo Young-woo''s whale imagination refers to the CGI scenes in which the autistic protagonist pictures a whale whenever she solves a problem perfectly.','In the drama "Extraordinary Attorney Woo," whenever protagonist Woo Young-woo comes up with a perfect solution, an imaginary scene featuring a large whale appears; when her answer falls short, a dolphin appears instead. A whale-themed quiz in the show, in which Woo answers that "whales cannot lay eggs," also became a talking point, and the device became a hugely popular meme throughout the drama''s 2022 run.','A recurring visual device and line from the ENA drama "Extraordinary Attorney Woo" (2022).','Used figuratively to describe having a great idea.',null,array['우영우 고래 상상','Woo Young-woo Whale Quiz','우영우 고래 퀴즈'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('b445d585-f77d-4ed3-9a92-f6dc413c058b','en','shinhwa-top','Shinhwa - "T.O.P"','"T.O.P" is Shinhwa''s 1999 title track that became a hit by sampling Tchaikovsky''s "Swan Lake."','Released as the title track of Shinhwa''s second album in 1999, "T.O.P" drew attention for sampling Tchaikovsky''s "Swan Lake" and became a turning point where Shinhwa''s precise choreography and tight group dancing began to build serious popularity.','Shinhwa topped music chart shows with "T.O.P (Twinkling of Paradise)," the title track of their 1999 second album. The song drew attention for its unique fusion of classical and dance music, sampling the melody of "Scene," a piece from Tchaikovsky''s ballet "Swan Lake," throughout the track. Because the concept of sampling was still unfamiliar in Korea at the time, it sparked some plagiarism controversy, though many now view it as a legitimate use that credited the original work rather than true plagiarism. The song is regarded as a defining hit of the first-generation idol era and one of Shinhwa''s earliest signature tracks.','Can be cited as a representative example of a classical-sampling dance song.',null,array['신화 ''T.O.P''','T.O.P'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('3dc10a1e-6671-46b5-8281-8ffd149f4d5d','en','jjilleoman','Jjilleoman','Jjilleoman is a stick-figure Flash animation series based on the Zealot unit from StarCraft.','Running from the late 1990s through the early 2000s on sites like Yupgihouse and Humor World, this stick-figure Flash animation series was known for its characters modeled after the Zealot unit from the online game StarCraft.','Jjilleo (Jjilleoman) was a stick-figure Flash animation created by an artist under the pen name "Bukseoni." It gained popularity serialized on Flash community sites such as Yupgihouse and Humor World in the late 1990s and early 2000s. Featuring a character based on StarCraft''s Zealot unit, it was considered one of the leading series in the then-popular stick-figure action genre. Even after Yupgihouse declined in the early 2000s and overall interest in stick-figure Flash animation waned, the creator continued working through sites like "Flash365" and "Jujeonja.com," and opened a Naver cafe in 2008 to share settings and production updates, though the series was not continued afterward.','Can be cited as an offshoot of the Jjolraman-style stick-figure animation culture.',null,array['찔러맨','Jjilleo','찔러'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8fc75170-5bff-4ac0-ad4b-146ec93e06e5','en','freeze-jepeupeu','"Freeze!" (Jepeupeu Remix)','"Freeze!" is a meme song by YouTuber Jepeupeu that remixes a line from "Squid Game" Season 2 into a musical-style number.','In "Squid Game" Season 2, Seong Gi-hun (played by Lee Jung-jae) sternly shouts "Freeze!" at contestants during a game of Red Light, Green Light. YouTuber Jepeupeu arranged and remixed this scene into a musical-style number. The upbeat, hopeful arrangement, contrasting sharply with the original''s grim tone, became the joke, and the video passed 1.6 million views within five days of release.','A musical remix of a line from "Squid Game" Season 2, created by YouTuber Jepeupeu.','Used as a remix meme that playfully flips a serious situation.',null,array['얼음(제프프)','Squid Game Freeze Musical','오징어게임 얼음 뮤지컬'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1e9b2e28-60a2-49d0-a2e8-96ef5fc847bd','en','pop-cat','Pop Cat','Pop Cat is a meme, based on a video of a cat opening and closing its mouth while eyeing a bug, that became a click-counter game trend in Korea in late 2020.','A short video edited from footage of a cat named "Oatmeal" chattering its mouth while watching a bug, with a mouth-popping sound effect added, became a worldwide meme. It started trending in Korea in December 2020 and remained popular through January 2021, and in August 2021 Korean netizens mass-clicked in a country-ranking click event to push Korea''s ranking up.','A worldwide meme edited from footage of a cat named "Oatmeal," which trended in Korea starting December 2020.','Good to bring up when talking about a simple, repetitive, funny GIF.',null,array['팝캣','Pop Cat','뻐끔뻐끔 고양이'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('2b77cfc7-5ef3-4ae0-accc-970b6df9630c','en','gag-concert-mappagi','Gag Concert''s "Mappagi"','"Mappagi" is a 2006 Gag Concert sketch famous for its forehead-slapping physical comedy.','Airing from August 2006, this Gag Concert sketch featured Jung Jong-chul, made up as a bald character, performing forehead-slapping physical comedy along with the catchphrase "Neighborhood boss Mappagi! Who do you think you''re looking at, Mappagi!"','A KBS "Gag Concert" sketch that aired from August 27, 2006 to March 2007, featuring Jung Jong-chul, Kim Si-deok, Kim Dae-beom, and Park Jun-hyung performing forehead-tapping physical comedy. Its prototype is known to be "Geondal Geondal Geondari," a stage show performed at a small theater in Daehangno six years earlier, which was reworked for Gag Concert and became hugely popular. It was credited with reviving Gag Concert during a slump and was even made into a theatrical children''s film directed by Kim Hyun-soo. At the time, Pohang Steelers'' foreign player Denilson picked up the nickname "Depagi" after copying the Mappagi move as a goal celebration.','Used playfully, often paired with physical comedy.',null,array['개그콘서트 마빡이','Mappagi','마빡이'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('cc07b206-7c81-4780-a51e-17e139ba332f','en','yoajeong','Yoajeong','Yoajeong is a yogurt ice cream brand whose "honey combo" toppings became a viral meme on social media in 2024.','Yoajeong, a yogurt ice cream brand known for its honeycomb honey and fresh fruit toppings, went viral on Instagram and TikTok in the summer of 2024. An anecdote also made the rounds in which a fan asked IU if she knew about "Yoajeong" and she misheard it as "yojeong" (fairy). It became known as a must-try dessert among young women, with a flood of content recommending honey-topping combinations.','The brand "Yogurt Ice Cream''s Classic" (Yoajeong) spread on Instagram and TikTok in 2024.','Used when talking about desserts or must-have trendy items.',null,array['요아정','Yogurt Ice Cream''s Classic','요거트아이스크림의정석','요아정 꿀조합'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('0af67ded-43c6-4273-a375-e0c5c6596dad','en','dubai-chocolate-syndrome','Dubai Chocolate Syndrome','Dubai Chocolate Syndrome refers to the pistachio cream chocolate trend that spread through TikTok and swept Korea in 2024.','The trend began in December 2023 when a video from a Dubai chocolate brand went viral on TikTok for months, before landing in Korea in the summer of 2024. Convenience stores across the country sold out repeatedly as people searched for the chocolate, filled with kadayif (Middle Eastern shredded pastry) and pistachio cream. The craze even caused pistachio prices to spike.','A TikTok video out of Dubai spread starting in late 2023 and became a trend in Korea in 2024.','Used when talking about trending desserts or viral items from abroad.',null,array['두바이초콜릿 신드롬','Dubai Chocolate','두바이 초콜릿'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('69528101-01d5-443d-8077-db730f6ceed1','en','our-mom-mom-meme','"Our Mom-Mom" Meme','The "Our Mom-Mom" meme comes from Stray Kids'' Changbin rewriting the chorus of NewJeans'' "OMG" into a self-answered brag in 2023.','In early 2023, on Stray Kids'' self-produced content "Seukeuz Talker," Changbin changed the chorus of NewJeans'' "OMG" - "Oh my oh my God" - into "Who gave birth to someone this pretty? My mom, my mom did," which became a meme. His deadpan, self-satisfied delivery of the question-and-answer was what made it funny, and it led to parodies from other idols and fans.','Stray Kids'' self-produced content "Seukeuz Talker," episode 56 (around January 2023).','Used to humorously express self-praise.',null,array['우리 엄마엄마가 밈','Eomma-eomma-ga','엄마엄마가','창빈 엄마엄마가'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('db138d82-b0be-468c-b65c-b1af8b876628','en','jimin-like-crazy-challenge','Jimin''s "Like Crazy" Challenge','The "Like Crazy" Challenge is a 2023 global dance challenge based on the choreography of BTS Jimin''s solo debut single "Like Crazy."','"Like Crazy," the title track of Jimin''s first solo studio album released in March 2023, achieved worldwide success, including hitting No. 1 on the Billboard Hot 100, and a dance challenge based on the song spread across social media alongside it. Artists such as Taeyang also took part in the challenge.','A promotional challenge for "Like Crazy," the title track of Jimin''s first solo album "FACE" (released March 24, 2023).','Used to refer to a global K-pop solo dance challenge meme.',null,array['지민 Like Crazy 챌린지','Like Crazy Challenge','라이크 크레이지 챌린지','지민 솔로 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('a6efab03-d735-44ad-bbe0-a85d0eb870e5','en','sechskies-disbandment','Sechskies'' Disbandment','Sechskies'' disbandment refers to the first-generation idol group''s sudden breakup announcement and farewell stage.','Sechskies, who debuted in 1997, held a press conference on May 18, 2000, to announce their sudden disbandment, and wrapped up their activities two days later with a farewell performance at the Dream Concert. It was later revealed that leader Eun Ji-won had been the one to first propose disbanding, saying the group should leave while they were still loved by fans.','The members'' voluntary disbandment announcement on May 18, 2000, followed by a farewell stage at the Dream Concert on May 20.','Used when reminiscing about first-generation idol culture and early-2000s fandom.',null,array['젝스키스 해체','Sechskies Disbandment Announcement','젝키 해체 선언'],'[{"text": "Whenever people talk about first-generation idol disbandments, Sechskies comes to mind.", "situation": "KakaoTalk"}, {"text": "That farewell stage was seriously tear-jerking.", "situation": "Social media comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d8827144-e48f-4972-b9d1-34793e2a790c','en','heopop-slime-challenge','Heopop''s Slime Challenge','Heopop''s Slime Challenge refers to the 2015 boom in making and playing with slime that spread to Korea via YouTube.','A slime craze that began abroad around 2015 landed in Korea through YouTube, and experiment/kids-content creators including Heopop became hugely popular among young viewers by posting videos of them making slime in various colors and textures. Heopop signed with CJ''s MCN DIA TV in April 2015 and became one of the leading creators of this trend.','A slime trend that started abroad in 2015 spread to Korea via YouTube.','Cited as an example of a trend in kids/experiment content.','Some slime ingredients were involved in controversy over harmful substances, so keep this in mind when referencing safety.',array['허팝 액체괴물(슬라임) 챌린지','Slime Challenge','액괴','슬라임 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('34db3403-c1e5-4bbf-8d3c-2a932f453d41','en','tokyo-olympics-pictogram-meme','Tokyo Olympics Pictogram Meme','The Tokyo Olympics Pictogram Meme grew out of a mime performance introducing the Olympic sports at the 2021 Tokyo Olympics opening ceremony that went viral worldwide.','At the Tokyo Olympics opening ceremony on July 23, 2021, the Japanese dance-and-mime duo GABEZ performed a "pictogram sequence," acting out all 50 Olympic sports with their bodies. The performance video surpassed 10 million views on YouTube, and a wave of parody content followed both in Korea and abroad, along with nicknames like "Pictogram Man" and "Pictojwa" (roughly, "the master of pictograms").','GABEZ''s pictogram performance at the Tokyo 2020 Olympics opening ceremony (July 23, 2021).','Good to bring up when talking about a performance that cleverly expresses something through body movement.',null,array['도쿄올림픽 픽토그램 밈','Pictogram Man','픽토그램맨','Pictojwa','픽토좌'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
